const auto color_string = [dwg](const char *text) -> std::string {
  if (!text)
    return std::string();
  if (dwg && IS_FROM_TU_DWG(dwg)) {
    std::unique_ptr<char, decltype(&free)> utf8(
      bit_convert_TU(reinterpret_cast<BITCODE_TU>(const_cast<char*>(text))), &free);
    return utf8 ? std::string(utf8.get()) : std::string();
  }
  // R2004 names keep their existing code-page bytes for the JS layer to decode.
  return std::string(text);
};
